// Usage: node build-bundle.cjs /path/to/node_modules/pdfjs-dist
// The build environment must provide esbuild 0.25.12.
const fs = require('node:fs');
const path = require('node:path');
const esbuild = require('esbuild');

const sourceDir = path.resolve(process.argv[2]);
const {version} = require(path.join(sourceDir, 'package.json'));

function readData(dir, extension) {
  const location = path.join(sourceDir, dir);
  return Object.fromEntries(fs.readdirSync(location).sort()
    .filter(file => extension.test(file))
    .map(file => [file, fs.readFileSync(path.join(location, file)).toString('base64')]));
}

const data = {
  cMapUrl: readData('cmaps', /\.bcmap$/),
  standardFontDataUrl: readData('standard_fonts', /\.(pfb|ttf)$/),
};

esbuild.buildSync({
  stdin: {
    resolveDir: path.join(sourceDir, 'legacy/build'),
    contents: `
      import * as pdfjs from './pdf.min.mjs';
      import './pdf.worker.min.mjs';
      const binaryData = ${JSON.stringify(data)};
      globalThis.pdfjsLib = pdfjs;
      globalThis.BaigePdfBinaryDataFactory = class {
        async fetch({kind, filename}) {
          const encoded = binaryData[kind]?.[filename];
          if (typeof encoded !== 'string') throw new Error('Unsupported PDF resource');
          return Uint8Array.from(atob(encoded), char => char.charCodeAt(0));
        }
      };
    `,
  },
  outfile: path.join(__dirname, 'pdf-text.bundle.js'),
  platform: 'browser',
  format: 'iife',
  bundle: true,
  minify: true,
  legalComments: 'inline',
  banner: {js: `/* PDF.js ${version}. Generated by build-bundle.cjs. See local license files. */`},
  define: {'import.meta.url': '""'},
});

for (const [source, destination] of [
  ['LICENSE', 'LICENSE'],
  ['cmaps/LICENSE', 'LICENSE-CMAPS'],
  ['standard_fonts/LICENSE_FOXIT', 'LICENSE-FOXIT'],
  ['standard_fonts/LICENSE_LIBERATION', 'LICENSE-LIBERATION'],
]) {
  fs.copyFileSync(path.join(sourceDir, source), path.join(__dirname, destination));
}
